+func TestValidateSession_WrongToken_Returns401(t *testing.T) {
+	gin.SetMode(gin.TestMode)
+	r := gin.New()
+	r.Use(serviceauth.RequireServiceToken("correct-token"))
+	r.POST("/internal/sessions/validate", func(c *gin.Context) {
+		c.Status(http.StatusOK)
+	})
+
+	body, _ := json.Marshal(map[string]string{"cookie_value": "some-cookie"})
+	w := httptest.NewRecorder()
+	req := httptest.NewRequest(http.MethodPost, "/internal/sessions/validate", bytes.NewReader(body))
+	req.Header.Set("Authorization", "Bearer wrong-token")
