--- /dev/null
+++ b/internal/httpapi/session_decode.go
@@ -0,0 +1,45 @@
+package httpapi
+
+import (
+	"bytes"
+	"encoding/gob"
+	"fmt"
+	"time"
+
+	"github.com/google/uuid"
+)
+
+// scsPayload mirrors the internal struct that scs/GobCodec uses to encode
+// session data.  The data column in the sessions table contains a gob-encoded
+// value of exactly this shape.
+type scsPayload struct {
+	Deadline time.Time
+	Values   map[string]interface{}
+}
+
+// extractUserIDFromSessionData decodes the gob payload written by scs and
+// returns the "user_id" value. Returns uuid.Nil if the key is absent.
+func extractUserIDFromSessionData(data []byte) (uuid.UUID, error) {
+	// scs stores string values as plain strings; register string so gob can
+	// decode map[string]interface{} entries.
+	gob.Register("")
+
+	var payload scsPayload
+	if err := gob.NewDecoder(bytes.NewReader(data)).Decode(&payload); err != nil {
+		return uuid.Nil, fmt.Errorf("decode session gob: %w", err)
+	}
+
+	raw, ok := payload.Values["user_id"]
+	if !ok {
+		return uuid.Nil, nil
+	}
+	str, ok := raw.(string)
+	if !ok {
+		return uuid.Nil, fmt.Errorf("user_id is not a string: %T", raw)
+	}
+	id, err := uuid.Parse(str)
+	if err != nil {
+		return uuid.Nil, fmt.Errorf("parse user_id UUID: %w", err)
+	}
+	return id, nil
+}
