+func TestHandleAuthStart_KnownProvider_GeneratesState(t *testing.T) {
+	mock := &mockProvider{name: "google", authURL: "https://accounts.google.com/o/oauth2/auth"}
+	providers := map[string]oauth.Provider{"google": mock}
+	_ = providers
+
+	// Test that generateState produces a non-empty value (integration with the real
+	// generateState function, which is in the same package).
+	for i := 0; i < 10; i++ {
+		state, err := generateState()
+		if err != nil {
+			t.Fatalf("generateState[%d]: %v", i, err)
+		}
+		if state == "" {
+			t.Fatal("empty state")
+		}
+	}
+}
+
+func TestAuthStart_UnknownProvider_404(t *testing.T) {
+	// Verify that the healthz route exists and unknown auth provider returns a
+	// meaningful response. We use a plain New() router (no DB).
+	r := New()
+
+	w := httptest.NewRecorder()
+	req := httptest.NewRequest(http.MethodGet, "/auth/unknown_provider/start", nil)
+	r.ServeHTTP(w, req)
