CREATE EXTENSION IF NOT EXISTS "pgcrypto";

-- Identity: users
CREATE TABLE users (
    id           UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
    email        TEXT        NOT NULL,
    display_name TEXT,
    avatar_url   TEXT,
    created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at   TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX idx_users_email_lower ON users (lower(email));

-- Identity: auth_identities (provider-side authentication)
CREATE TABLE auth_identities (
    id             UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id        UUID        NOT NULL REFERENCES users(id),
    provider       TEXT        NOT NULL,
    provider_sub   TEXT        NOT NULL,
    email          TEXT,
    email_verified BOOLEAN,
    created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (provider, provider_sub)
);

CREATE INDEX idx_auth_identities_user_id ON auth_identities (user_id);

-- Tenancy: organizations
CREATE TABLE organizations (
    id         UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
    slug       TEXT        NOT NULL UNIQUE,
    name       TEXT        NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Tenancy: memberships
CREATE TABLE memberships (
    id              UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id         UUID        NOT NULL REFERENCES users(id),
    organization_id UUID        NOT NULL REFERENCES organizations(id),
    role            TEXT        NOT NULL,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (user_id, organization_id)
);

CREATE INDEX idx_memberships_organization_id ON memberships (organization_id);

-- Tenancy: workspace_memberships (workspace_id is a cross-DB UUID — no FK)
CREATE TABLE workspace_memberships (
    id           UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id      UUID        NOT NULL REFERENCES users(id),
    workspace_id UUID        NOT NULL,
    created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (user_id, workspace_id)
);

CREATE INDEX idx_workspace_memberships_workspace_id ON workspace_memberships (workspace_id);

-- Onboarding: organization_invitations
CREATE TABLE organization_invitations (
    id                  UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
    organization_id     UUID        NOT NULL REFERENCES organizations(id),
    email               TEXT        NOT NULL,
    role                TEXT        NOT NULL,
    invited_by_user_id  UUID        REFERENCES users(id),
    workspace_ids       JSONB,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    expires_at          TIMESTAMPTZ,
    accepted_at         TIMESTAMPTZ,
    accepted_by_user_id UUID        REFERENCES users(id)
);

CREATE INDEX idx_org_invitations_org_email_lower ON organization_invitations (organization_id, lower(email));
CREATE INDEX idx_org_invitations_expires_at ON organization_invitations (expires_at);

-- Sessions: managed by alexedwards/scs/v2 + postgresstore
